207	    private static int? ParseRowIndexFromRange(string? range)
208	    {
209	        if (string.IsNullOrEmpty(range))
210	            return null;
211	
212	        var cellRange = range.Contains('!') ? range[(range.IndexOf('!') + 1)..] : range;
