1	using System.ComponentModel.DataAnnotations;
2	using System.Globalization;
3	
4	namespace InventoryManagement.Models;
5	
6	/// <summary>
7	/// Fields and cell-parsing helpers shared by the three inventory sheets
8	/// (PCB_Inventory, Tools_Inventory, Panel_Inventory).
9	/// </summary>
10	public abstract class InventoryItemBase
11	{
12	    /// <summary>
13	    /// 1-based row index in the spreadsheet, including the header row
14	    /// (row 1 = header). Used to locate the row for edit / delete / damage.
15	    /// </summary>
16	    public int RowIndex { get; set; }
17	
18	    [Display(Name = "Sl. No.")]
19	    public string SlNo { get; set; } = "";
20	
21	    [Display(Name = "Total Quantity")]
22	    [Range(1, 999999, ErrorMessage = "Total quantity must be at least 1.")]
23	    public int TotalQuantity { get; set; }
24	
25	    [Display(Name = "Remaining")]
26	    [Range(0, 999999, ErrorMessage = "Remaining cannot be negative.")]
27	    public int Remaining { get; set; }
28	
29	    [Display(Name = "Invoice No.")]
30	    public string InvoiceNo { get; set; } = "";
31	
32	    [Display(Name = "Cost per Unit (₹)")]
33	    [Range(0, 99999999, ErrorMessage = "Cost per unit cannot be negative.")]
34	    public decimal CostPerUnit { get; set; }
35	
36	    [Display(Name = "Total Cost (₹)")]
37	    public decimal TotalCost { get; set; }
38	
39	    [Display(Name = "Supplier")]
40	    public string Supplier { get; set; } = "";
41	
42	    [Display(Name = "Date of Purchase")]
43	    public string DateOfPurchase { get; set; } = "";
44	
45	    [Display(Name = "Remarks")]
46	    public string Remarks { get; set; } = "";
47	
48	    /// <summary>Rows at or below this stock level are highlighted in the UI.</summary>
49	    public const int LowStockThreshold = 5;
50	
51	    public bool IsLowStock => Remaining < LowStockThreshold;
52	
53	    // ---- Cell parsing helpers -------------------------------------------------
54	    // Sheets API returns numbers as double, empty trailing cells are omitted.
55	
56	    protected static string Cell(IList<object> row, int index)
57	        => index < row.Count ? row[index]?.ToString()?.Trim() ?? string.Empty : string.Empty;
58	
59	    protected static int CellInt(IList<object> row, int index)
60	    {
61	        var text = Cell(row, index);
62	        return decimal.TryParse(text, NumberStyles.Any, CultureInfo.InvariantCulture, out var v)
63	            ? (int)v
64	            : 0;
65	    }
66	
67	    protected static decimal CellDec(IList<object> row, int index)
68	        => decimal.TryParse(Cell(row, index), NumberStyles.Any, CultureInfo.InvariantCulture, out var v)
69	            ? v
70	            : 0m;
71	}
