3	using Microsoft.AspNetCore.Mvc.RazorPages;
4	
5	namespace InventoryManagement.Pages.Damage;
6	
7	public class HistoryModel : PageModel
8	{
9	    private readonly GoogleSheetsService _sheets;
10	
11	    public List<DamageRecord> Records { get; private set; } = new();
12	    public int TotalUnitsDamaged { get; private set; }
13	    public decimal TotalValueLoss { get; private set; }
14	
15	    public HistoryModel(GoogleSheetsService sheets) => _sheets = sheets;
16	
17	    public async Task OnGetAsync()
18	    {
19	        var rows = await _sheets.GetRowsAsync(DamageRecord.SheetName);
20	
21	        Records = new List<DamageRecord>();
22	        // Newest records first.
23	        for (int i = rows.Count - 1; i >= 1; i--)
24	        {
25	            var record = DamageRecord.FromRow(rows[i], i + 1);
26	            Records.Add(record);
