1	using System.ComponentModel.DataAnnotations;
2	
3	namespace InventoryManagement.Models;
4	
5	/// <summary>
6	/// One row of a category inventory sheet (Electronics_Inventory,
7	/// Electrical_Inventory, Tools_Inventory or Modules_Inventory). All four
8	/// sheets share the same column layout, so a single model covers them.
9	/// </summary>
10	public sealed class InventoryItem
11	{
12	    public const string Electronics = "Electronics";
13	    public const string Electrical = "Electrical";
14	    public const string Tools = "Tools";
15	    public const string Modules = "Modules";
16	
17	    public const int ColumnCount = 11;
18	
19	    // 0-based column indexes, matching the sheets' header rows.
20	    private const int ColUniqueCode = 0;
21	    private const int ColComponentName = 1;
22	    private const int ColBrand = 2;
23	    private const int ColTotalQuantity = 3;
24	    private const int ColRemaining = 4;
25	    private const int ColInvoiceNo = 5;
26	    private const int ColCostPerUnit = 6;
27	    private const int ColTotalCost = 7;
28	    private const int ColSupplier = 8;
29	    private const int ColDateOfPurchase = 9;
30	    private const int ColRemarks = 10;
31	
32	    /// <summary>1-based row index in the spreadsheet (row 1 = header).</summary>
33	    public int RowIndex { get; set; }
34	
35	    [Display(Name = "Unique Code")]
36	    public string UniqueCode { get; set; } = "";
37	
38	    [Display(Name = "Component Name")]
39	    public string ComponentName { get; set; } = "";
40	
41	    [Display(Name = "Brand")]
42	    public string Brand { get; set; } = "";
43	
44	    [Display(Name = "Total Quantity")]
45	    [Range(1, 999999, ErrorMessage = "Total quantity must be at least 1.")]
46	    public int TotalQuantity { get; set; }
47	
48	    [Display(Name = "Remaining")]
49	    [Range(0, 999999, ErrorMessage = "Remaining cannot be negative.")]
50	    public int Remaining { get; set; }
51	
52	    [Display(Name = "Invoice No.")]
53	    public string InvoiceNo { get; set; } = "";
54	
55	    [Display(Name = "Cost per Unit (₹)")]
56	    [Range(0, 99999999, ErrorMessage = "Cost per unit cannot be negative.")]
57	    public decimal CostPerUnit { get; set; }
58	
59	    [Display(Name = "Total Cost (₹)")]
60	    public decimal TotalCost { get; set; }
61	
62	    [Display(Name = "Supplier")]
63	    public string Supplier { get; set; } = "";
64	
65	    [Display(Name = "Date of Purchase")]
66	    public string DateOfPurchase { get; set; } = "";
67	
68	    [Display(Name = "Remarks")]
69	    public string Remarks { get; set; } = "";
70	
